import {submissionView} from './submission-ui.js';
import {submissionProfile} from './runtime-config.js';
import {loginView, registrationView, changePasswordView, recoveryView, accountsView} from './auth-ui.js';
import {benchmark} from './benchmark-ui.js';
import {teams, teamById, matches, matchesFor, matchFor, nav, pageTitles, boardAt} from './data.js';
import {icon, logo, avatar, badge, btn, navLink, sectionHead, board, matchCard, escapeHTML as esc, emptyState, pieceIcon} from './ui.js';
const field = (label, input, note='') => `<label class="field"><span>${label}</span>${input}${note?`<small>${note}</small>`:''}</label>`;
const stat = (label, value, foot, ico) => `<div class="stat"><div class="stat-icon">${icon(ico)}</div><p class="stat-label">${label}</p><div class="stat-value">${value}</div><p class="stat-foot">${foot}</p></div>`;
const tabs = (items, selected, action) => `<div class="tabs" role="group" aria-label="Bộ lọc">${items.map(([id,text])=>`<button class="tab-btn ${selected===id?'active':''}" data-action="${action}" data-value="${id}" aria-pressed="${selected===id}">${text}</button>`).join('')}</div>`;
const search = (id, value, placeholder) => `<div class="search-field">${icon('search')}<input class="input" id="${id}" data-filter="${id}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${placeholder}"></div>`;
const select = (id, value, options) => `<select class="select" id="${id}" data-filter="${id}" aria-label="${id==='group'?'Lọc bảng đấu':'Chọn vòng đấu'}">${options.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${l}</option>`).join('')}</select>`;
const groups = [['all','Tất cả bảng'],['A','Bảng A'],['B','Bảng B']];
const head = (title, sub, actions='', kicker='UET BOT ARENA / MÙA 2026') => `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`;
const footer = () => `<footer class="footer"><span>© 2026 UET Bot Arena <span class="sep">·</span> Bản giao diện demo · Dữ liệu minh họa</span><a href="#/guide">Tài liệu & thể lệ ${icon('arrow')}</a></footer>`;

export function shell(state, content) {
  const route=state.route;
  const initial=state.user?.initials||'KH';
  return `<div class="app-shell ${state.menuOpen?'menu-open':''}"><button class="menu-backdrop" data-action="menu" aria-label="Đóng menu"></button><aside class="sidebar"><a class="brand" href="#/home" aria-label="UET Bot Arena, trang chủ">${logo()}<span><strong>UET Bot Arena</strong><small>CODE. COMPETE. CONNECT.</small></span></a><div class="season"><span class="season-icon">${icon('trophy')}</span><span>Freshman Cup 2026<small>Vòng bảng đang diễn ra</small></span></div><div class="nav-label">ĐẤU TRƯỜNG</div><nav aria-label="Điều hướng chính">${nav.map(([id,label,ico])=>`<a href="#/${id}" class="nav-item ${route===id||(id==='live'&&['arena','replay'].includes(route))?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ico)}${label}${id==='live'?'<span class="nav-count">3</span>':''}</a>`).join('')}<div class="nav-label secondary">TÀI NGUYÊN</div><a class="nav-item ${route==='guide'?'active':''}" href="#/guide">${icon('book')}Tài liệu & thể lệ</a>${state.user?.role==='admin'?`<div class="nav-label secondary">BAN TỔ CHỨC</div><a href="#/admin/accounts" class="nav-item ${route==='admin'?'active':''}">${icon('shield')}Tài khoản đội thi</a>`:''}<button class="nav-item" data-action="support" style="width:100%;border:0;background:transparent;text-align:left">${icon('info')}Trợ giúp</button></nav><div class="sidebar-bottom"><div class="help-card">${icon('code')}<h3>Bot đầu tiên của bạn?</h3><p>Bắt đầu từ một ý tưởng nhỏ. Chúng mình có sẵn bot mẫu.</p><a href="assets/bot-starter-cpp.zip" download>Tải starter kit C++ ${icon('download')}</a></div><div class="profile"><span class="person-avatar">${esc(initial)}</span><div><strong>${esc(state.user?.name||'Khách tham quan')}</strong><small>${state.user?.role==='admin'?'Ban tổ chức · Demo':state.user?esc(state.teamName)+' · Demo':'Đăng nhập để quản lý đội'}</small></div>${state.user?`<button class="icon-btn" data-action="logout" aria-label="Đăng xuất và xem trang đăng nhập" title="Đăng xuất">${icon('logout')}</button>`:`<a class="icon-btn" href="#/login" aria-label="Đăng nhập">${icon('arrow')}</a>`}</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Mở menu" aria-expanded="${state.menuOpen}">${icon('menu')}</button><span>Freshman Cup 2026</span>${icon('chevron')}<strong>${pageTitles[route]||'Tổng quan'}</strong></div><div class="top-actions"><span class="connection-label"><i></i>Chế độ trải nghiệm</span><span class="demo-chip">DEMO UI</span><button class="icon-btn bell" data-action="notifications" aria-label="Xem thông báo">${icon('bell')}</button>${state.user?`<a href="#/login" class="top-avatar" aria-label="Mở trang đăng nhập">${esc(initial)}</a>`:`<a href="#/login" class="btn small top-login">Đăng nhập</a>`}</div></header><main class="page ${['arena','replay'].includes(route)?'arena-page':''}" id="main">${content}${footer()}</main></div></div>`;
}

export function home(state) {
  return `${head(`Chào ${esc(state.user?.name||'bạn')}, sẵn sàng thi đấu?`, 'Một ý tưởng mới. Một nước đi hay. Một trận đấu đáng nhớ.',navLink('submissions','Nộp phiên bản bot','btn primary','upload'))}<section class="hero"><div class="hero-copy"><div class="eyebrow">FRESHMAN CUP 2026 · VÒNG BẢNG</div><h2>Đấu trường của<br><span>những ý tưởng.</span></h2><p>Code bot theo cách của bạn. Cùng đồng đội thử chiến thuật,<br class="desktop-br"> học từ mỗi trận đấu và tiến xa hơn.</p><div class="hero-actions">${navLink('live','Vào đấu trường','btn light','arrow')}${navLink('guide','Khám phá luật chơi','text-link','chevron')}</div></div><div class="hero-art">${board(20,true)}<div class="hero-stamp"><strong>9 × 9</strong>BÚA · BAO · KÉO</div></div></section><div class="stats-grid">${stat('ĐỘI THAM GIA','32','<strong>128</strong> sinh viên năm nhất','users')}${stat('TRẬN ĐANG DIỄN RA','03','<strong>02</strong> đang đấu · 01 tạm dừng','radio')}${stat('THỨ HẠNG CỦA ĐỘI','#01','<strong>13 điểm</strong> · Bảng A','trophy')}${stat('BOT CỦA BẠN','v1.3.0','<strong>Đã chốt</strong> cho vòng 6','code')}</div><section>${sectionHead('Đang diễn ra','Những nước đi mới nhất, ngay tại đấu trường.',navLink('live','Xem tất cả'))}<div class="match-grid">${matchesFor(state).filter(m=>['live','paused'].includes(m.status)).map(m=>matchCard(m)).join('')}</div></section><div class="dashboard-bottom"><section class="panel">${sectionHead('Lịch đấu tiếp theo','Hẹn gặp bạn ở nước đi đầu tiên.',navLink('schedule','Lịch đầy đủ'))}<div class="table-wrap"><table><thead><tr><th>THỜI GIAN</th><th>CẶP ĐẤU</th><th>VÒNG</th><th></th></tr></thead><tbody>${matchesFor(state).filter(m=>m.status==='scheduled').slice(0,3).map(m=>`<tr><td><strong>${m.time}</strong><div class="date-cell">Hôm nay, 10/10</div></td><td><div class="team-cell">${avatar(teamById(m.a))}${teamById(m.a).name}</div><div class="date-cell" style="margin-left:37px;margin-top:4px">vs ${teamById(m.b).name}</div></td><td>${m.round} <span class="date-cell">/ ${m.group}</span></td><td><a class="icon-btn" href="#/arena/${m.id}" aria-label="Xem trận ${m.id}">${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div></section><section class="panel">${sectionHead('Bảng tin','Thông báo từ ban tổ chức.')}<div class="announcement"><div class="announcement-date"><strong>10</strong>TH10</div><div><h3>Vòng 6 đã bắt đầu</h3><p>Kiểm tra adapter và sẵn sàng vào phòng đấu.</p>${badge('live','Thông báo giải')}</div></div><div class="announcement"><div class="announcement-date"><strong>09</strong>TH10</div><div><h3>Chốt bot trước vòng đấu</h3><p>Phiên bản đã chốt sẽ được giữ xuyên suốt vòng.</p></div></div><div class="announcement"><div class="announcement-date"><strong>08</strong>TH10</div><div><h3>Workshop: từ greedy đến alpha-beta</h3><p>Bot mẫu và hướng dẫn có trong mục Tài liệu.</p><a class="text-link" href="#/guide" style="margin-top:7px;font-size:9px">Xem tài liệu ${icon('arrow')}</a></div></div></section></div>`;
}

export function live(state) {
  const list=matchesFor(state).filter(m=>['live','paused'].includes(m.status)&&(state.liveFilter==='all'||state.liveFilter===m.status)&&(state.group==='all'||m.group===state.group));
  return `${head('Trực tiếp từ đấu trường','Chọn một trận đấu. Theo dõi cách những ý tưởng trở thành chiến thuật.',btn('Làm mới','refresh','secondary','radio'))}<div class="filters">${tabs([['all','Tất cả trận · 3'],['live','Đang đấu · 2'],['paused','Tạm dừng · 1']],state.liveFilter,'live-filter')}<div class="filter-fields">${select('group',state.group,groups)}</div></div><div class="section-kicker"><span class="live-dot"></span>VÒNG 6 <span class="sep">/</span> HÔM NAY, 10 THÁNG 10</div>${list.length?`<div class="match-grid">${list.map(m=>matchCard(m)).join('')}</div>`:emptyState('Chưa có trận đấu ở bộ lọc này','Thử chọn bảng đấu hoặc trạng thái khác.')}<div class="info-note">${icon('info')}<span>Các trận và nước đi ở đây là dữ liệu minh họa. Mở phòng đấu để trải nghiệm cập nhật bàn cờ và xem lại từng lượt.</span></div><section style="margin-top:30px">${sectionHead('Tiếp theo trên sân','Các đội đã có lịch, đang chờ đến lượt.',navLink('schedule','Xem lịch'))}<div class="match-grid">${matchesFor(state).filter(m=>m.status==='scheduled').slice(0,3).map(m=>matchCard(m,true)).join('')}</div></section>`;
}

export function schedule(state) {
  const pool=state.drawConfirmed ? [...matchesFor(state).filter(m=>m.round!==7), ...state.drawPairs.map((pair,i)=>({id:`DRAW0${i+1}`,a:pair[0],b:pair[1],group:teamById(pair[0]).group,round:7,status:'scheduled',time:i<2?'15:00':'15:30'}))] : matches;
  const list=pool.filter(m=>(state.round==='all'||String(m.round)===state.round)&&(state.group==='all'||m.group===state.group)&&(state.scheduleFilter==='all'||(state.scheduleFilter==='upcoming'?m.status==='scheduled':state.scheduleFilter==='finished'?m.status==='finished':['live','paused'].includes(m.status))));
  const rounds=[...new Set(list.map(m=>m.round))].sort((a,b)=>a-b);
  return `${head('Lịch thi đấu','Mỗi cuộc đối đầu là một cơ hội để tiến bộ.',btn('Bốc thăm thử','draw','secondary','shuffle'))}<div class="filters">${tabs([['all','Tất cả'],['running','Đang diễn ra'],['upcoming','Sắp tới'],['finished','Đã kết thúc']],state.scheduleFilter,'schedule-filter')}<div class="filter-fields">${select('round',state.round,[['all','Tất cả vòng'],['3','Vòng 3'],['4','Vòng 4'],['5','Vòng 5'],['6','Vòng 6'],['7','Vòng 7']])}${select('group',state.group,groups)}</div></div><div class="schedule-day">${icon('calendar')}Thứ Bảy, 10 tháng 10 năm 2026 <span class="sep">·</span> UTC+7</div>${rounds.length?rounds.map(round=>`<section class="panel schedule-block"><div class="schedule-round-title"><strong>Vòng ${round}</strong><span>${list.filter(m=>m.round===round).length} trận đấu</span></div>${list.filter(m=>m.round===round).map(m=>`<div class="schedule-row"><div class="schedule-time"><strong>${m.time}</strong><small>${m.id}</small></div><a class="team-cell" href="#/team/${m.a}">${avatar(teamById(m.a))}${teamById(m.a).name}</a><span class="versus">${m.score||'vs'}</span><a class="team-cell away" href="#/team/${m.b}">${teamById(m.b).name}${avatar(teamById(m.b))}</a>${badge(m.status)}${navLink(`${m.status==='finished'?'replay':'arena'}/${m.id}`,m.status==='finished'?'Replay':'Xem trận','btn small','')}</div>`).join('')}</section>`).join(''):emptyState('Không có trận phù hợp','Chọn lại vòng đấu hoặc trạng thái để xem lịch.')}<div class="info-note">${icon('clock')}<span>Thời gian hiển thị theo UTC+7. Bốc thăm thử chỉ thay đổi lịch demo trong trình duyệt của bạn; lịch giải chính thức do ban tổ chức chốt.</span></div>`;
}

export function standings(state) {
  const searchText=state.teamSearch.toLowerCase();
  const list=teams.filter(t=>(state.group==='all'||t.group===state.group)&&t.name.toLowerCase().includes(searchText)).sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name):state.sort==='wins'?b.win-a.win||b.points-a.points:b.points-a.points);
  return `${head('Bảng xếp hạng','Mỗi nước đi đều có giá trị. Mỗi vòng đấu đều có cơ hội.',btn('Tải bảng điểm','export-standings','secondary','download'))}<div class="stats-grid">${stat('ĐỘI CỦA BẠN','#01','Dẫn đầu <strong>bảng A</strong>','trophy')}${stat('TỔNG ĐIỂM','13','4 thắng · 1 hòa · 0 thua','grid')}${stat('TỶ LỆ THẮNG','80%','Sau <strong>5 trận</strong> chính thức','shield')}${stat('VÒNG ĐANG ĐẤU','06 / 07','Vòng bảng · Freshman Cup','calendar')}</div><div class="filters">${tabs([['all','Tất cả bảng'],['A','Bảng A'],['B','Bảng B']],state.group,'group-filter')}<div class="filter-fields">${search('teamSearch',state.teamSearch,'Tìm tên đội...')}</div></div><section class="panel"><div class="table-wrap"><table class="standings-table"><thead><tr><th>HẠNG</th><th><button class="sortable" data-action="sort" data-value="name">ĐỘI THI ↕</button></th><th>BẢNG</th><th>TRẬN</th><th><button class="sortable" data-action="sort" data-value="wins">THẮNG ↕</button></th><th>HÒA</th><th>THUA</th><th><button class="sortable" data-action="sort" data-value="points">ĐIỂM ↓</button></th><th>5 TRẬN GẦN NHẤT</th></tr></thead><tbody>${list.map(t=>`<tr class="${t.id==='byte'?'ours':''}"><td><span class="rank ${t.rank<=3?'top':''}">${String(t.rank).padStart(2,'0')}</span></td><td><a href="#/team/${t.id}" class="team-cell">${avatar(t)}${t.name}${t.id==='byte'?'<span class="overview-highlight">Đội của bạn</span>':''}</a></td><td><span class="badge">${t.group}</span></td><td>${t.played}</td><td>${t.win}</td><td>${t.draw}</td><td>${t.loss}</td><td><span class="points">${t.points}</span></td><td><div class="form">${t.form.map(f=>`<span class="${f}" title="${f==='W'?'Thắng':f==='D'?'Hòa':'Thua'}">${f==='W'?'T':f==='D'?'H':'B'}</span>`).join('')}</div></td></tr>`).join('')}</tbody></table>${list.length?'':emptyState('Không tìm thấy đội','Thử một tên đội khác hoặc bỏ bộ lọc.')}</div><div class="table-legend"><span><i class="legend-block"></i>Đội của bạn</span><span>T · Thắng</span><span>H · Hòa</span><span>B · Thua</span><span style="margin-left:auto">Thắng 3 điểm · Hòa 1 điểm · Thua 0 điểm</span></div></section><p class="sort-hint">Nhấn tên cột Đội thi, Thắng hoặc Điểm để sắp xếp. Hạng hiển thị là thứ hạng tổng hợp trong dữ liệu demo.</p>`;
}

export function team(state) {
  const t=teamById(state.detailId||'byte'),ours=t.id==='byte';
  const history=matchesFor(state).filter(m=>m.status==='finished'&&(m.a===t.id||m.b===t.id));
  const members=state.members;
  const next=matchesFor(state).find(m=>m.status==='scheduled'&&(m.a===t.id||m.b===t.id));
  const active=state.submissions.find(s=>s.active)||state.submissions[0];
  return `${head(ours?'Đội của tôi':'Hồ sơ đội','Chiến thuật tốt bắt đầu từ một đội ăn ý.',ours?btn('Chỉnh sửa đội','edit-team','secondary','settings'):'')}<section class="panel"><div class="team-profile-header">${avatar(t,'large')}<div><div class="eyebrow">ĐỘI THI / BẢNG ${t.group}</div><h2>${ours?esc(state.teamName):t.name}</h2><p>${ours?esc(state.teamMotto):'Code, thử nghiệm và tiến bộ qua từng trận đấu.'}</p></div><div class="page-actions">${badge('accepted','Đã đăng ký giải')}${badge('neutral','UET · Khóa QH-2026')}</div></div><div class="team-info-row"><div>MÃ ĐỘI<strong>UET-${t.tag}-2026</strong></div><div>THÀNH VIÊN<strong>${ours?members.length:4} / 4 người</strong></div><div>THAM GIA<strong>01/10/2026</strong></div><div>THỂ THỨC<strong>Freshman Cup · Vòng bảng</strong></div></div></section><div class="stats-grid team-stats">${stat('XẾP HẠNG','#'+String(t.rank).padStart(2,'0'),'Bảng '+t.group,'trophy')}${stat('ĐIỂM SỐ',t.points,t.played+' trận chính thức','grid')}${stat('THẮNG / HÒA / THUA',`${t.win} / ${t.draw} / ${t.loss}`,'Chỉ tính trận chính thức','shield')}${stat('TỶ LỆ THẮNG',Math.round(t.win/t.played*100)+'%','Tiếp tục tiến lên','radio')}</div><div class="team-layout"><div class="content-stack">${ours?`<section class="panel">${sectionHead('Thành viên',members.length+' thành viên · Tối đa 4 người',`<span class="badge">Đội trưởng quản lý</span>`)}${members.map(m=>`<div class="member-row"><span class="person-avatar" style="background:${m.color}">${esc(m.initials)}</span><div><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small></div>${badge(m.role==='Đội trưởng'?'accepted':'neutral',m.role)}${m.role==='Đội trưởng'?'':`<button class="icon-btn" data-action="remove-member" data-email="${esc(m.email)}" aria-label="Xóa ${esc(m.name)} khỏi đội demo">${icon('x')}</button>`}</div>`).join('')}<div class="invite-row">${icon('users')}<span>${members.length<4?'Còn '+(4-members.length)+' vị trí trong đội':'Đội đã đủ 4 thành viên'}</span>${btn('Mời thành viên','invite','small','plus',members.length>=4?'disabled':'')}</div></section>`:''}<section class="panel">${sectionHead('Lịch sử thi đấu','Các trận chính thức và replay của đội.')}<div class="table-wrap"><table><thead><tr><th>ĐỐI THỦ</th><th>VÒNG</th><th>KẾT QUẢ</th><th></th></tr></thead><tbody>${history.map(m=>`<tr><td><a class="team-cell" href="#/team/${m.a===t.id?m.b:m.a}">${avatar(teamById(m.a===t.id?m.b:m.a))}${teamById(m.a===t.id?m.b:m.a).name}</a></td><td>${m.round}</td><td>${badge(m.score.startsWith('½')?'neutral':'accepted',m.score.startsWith('½')?'Hòa · '+m.score:(m.a===t.id?'Thắng':'Thua')+' · '+m.score)}</td><td>${navLink('replay/'+m.id,'Replay','text-link','play')}</td></tr>`).join('')}</tbody></table>${history.length?'':emptyState('Chưa có trận đã kết thúc','Kết quả sẽ xuất hiện sau khi trận đấu hoàn tất.')}</div></section></div><div class="content-stack">${ours?`<section class="panel">${sectionHead('Bot đang sử dụng','Phiên bản đã chốt cho vòng 6.') }<div class="bot-summary"><div class="bot-summary-title"><span class="bot-file-icon">${icon('code')}</span><div><strong>Knight <span class="code-tag">${active.version}</span></strong><small>${submissionProfile(active).label} · ${active.size}</small></div></div><div class="key-value"><span>Submission</span><strong>${active.id}</strong></div><div class="key-value"><span>Trạng thái</span>${badge('locked')}</div><div class="key-value"><span>Chốt lúc</span><strong>10/10/2026 · 13:45</strong></div><a class="btn full" style="margin-top:17px" href="#/submissions">Quản lý phiên bản ${icon('arrow')}</a></div></section>`:''}<section class="panel next-match"><div class="eyebrow">TRẬN ĐẤU TIẾP THEO</div><h3>${next?teamById(next.a).name+' vs '+teamById(next.b).name:t.name+' · Chờ lịch mới'}</h3><p>${next?`Hôm nay, ${next.time} · Bảng ${t.group} · Vòng ${next.round}`:'Chưa có lịch trận tiếp theo'}</p>${next?navLink('arena/'+next.id,'Xem phòng đấu','btn primary','arrow'):navLink('schedule','Xem lịch đấu','btn primary','arrow')}</section></div></div>`;
}

export function submissions(state) { return submissionView(state); }

export function arena(state, replay=false) {
  const match=matchFor(state,state.detailId)||matches[0];
  if(state.detailId&&!matchFor(state,state.detailId))return head('Không tìm thấy trận đấu','Trận này chưa có trong lịch demo.','')+emptyState('Trở lại lịch thi đấu','Chọn một trận từ mục Lịch thi đấu để tiếp tục.');
  const a=teamById(match.a),b=teamById(match.b),step=replay?state.replayStep:state.liveStep;
  const {moves}=boardAt(step), latest=moves.at(-1),waiting=match.status==='scheduled',paused=!replay&&!waiting&&(match.status==='paused'||state.demoPaused);
  const clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
  const moveHistory=moves.map((m,i)=>`<div class="history-row"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="side-dot ${m.side}"></span><span class="move">${m.from} ${icon('arrow')} ${m.to}</span><span class="time">${m.duration}</span></div>`).join('');
  return `<div class="page-heading arena-heading"><div><div class="eyebrow">FRESHMAN CUP / VÒNG ${match.round} / BẢNG ${match.group}</div><h1>${replay?'Xem lại trận đấu':'Phòng thi đấu'} <span style="font-family:monospace;font-weight:400;color:#9aaa91">#${match.id}</span>${badge(replay?'finished':waiting?'scheduled':paused?'paused':match.status)}</h1><p>${replay?'Từng nước đi, từng quyết định. Học từ trận đấu của bạn.':'Theo dõi trận đấu và diễn biến trên bàn cờ.'}</p></div><div class="page-actions">${btn('Chia sẻ','share','secondary','link')}${replay?navLink('live','Đấu trường','btn','radio'):navLink('replay/'+match.id,'Xem replay','btn','play')}</div></div><div class="arena-grid"><div class="arena-main"><div class="players"><div class="player-info">${avatar(a,'medium')}<div><strong>${a.name}</strong><small>PHÍA XANH LÁ ${!replay&&step%2===0?'· ĐẾN LƯỢT':''}</small><div class="player-clock ${step%2===0?'active':''}">${clock(300-Math.floor(step*.8))}</div></div></div><span class="versus">VS</span><div class="player-info">${avatar(b,'medium')}<div><strong>${b.name}</strong><small>PHÍA XANH DƯƠNG ${!replay&&step%2?'· ĐẾN LƯỢT':''}</small><div class="player-clock ${step%2?'active':''}">${clock(300-Math.floor(step*.7))}</div></div></div></div><section class="board-panel"><div class="board-meta"><strong><span class="side-dot ${step%2?'blue':''}"></span>${replay?'Đang xem lượt '+step:waiting?'Chờ hai đội sẵn sàng':paused?'Diễn biến demo đang tạm dừng':'Lượt của '+(step%2?b.name:a.name)}</strong><span>OTT v2 <span class="sep">·</span> 9 × 9</span></div><div id="arena-board">${board(step,false,state.flipped)}</div><div class="board-bottom"><div class="board-legend"><span>${pieceIcon('r')}Búa</span><span>${pieceIcon('p')}Bao</span><span>${pieceIcon('s')}Kéo</span></div>${btn('Đổi góc nhìn','flip','ghost small','shuffle')}</div>${replay?`<div class="replay-controls"><label class="screen-reader-only" for="replay-range">Tua đến lượt</label><input type="range" id="replay-range" min="0" max="${state.replayTotal}" value="${step}" step="1"><div class="replay-buttons"><button class="icon-btn" data-action="replay-start" aria-label="Về đầu">${icon('rewind')}</button><button class="icon-btn" data-action="replay-prev" aria-label="Lượt trước" style="transform:rotate(180deg)">${icon('chevron')}</button>${btn(state.replayPlaying?'Tạm dừng':'Phát replay','replay-play','primary small',state.replayPlaying?'pause':'play')}<button class="icon-btn" data-action="replay-next" aria-label="Lượt tiếp">${icon('chevron')}</button><button class="icon-btn" data-action="replay-end" aria-label="Đến cuối">${icon('end')}</button><span>${step} / ${state.replayTotal} lượt</span></div></div>`:`<div class="demo-control"><span>Chạy thử diễn biến bàn cờ</span>${btn(state.demoPaused?'Tiếp tục demo':'Tạm dừng demo','demo-pause','small',state.demoPaused?'play':'pause')}${btn('Nước tiếp theo','next-move','small','chevron')}</div>`}</section></div><aside class="arena-side"><section class="panel">${sectionHead('Thông tin trận','',`<span class="badge">${icon('eye')} ${match.viewers||0}</span>`)}<div class="match-info-grid"><div><span>MÃ TRẬN</span><strong>${match.id}</strong></div><div><span>VÒNG ĐẤU</span><strong>Vòng ${match.round} · Bảng ${match.group}</strong></div><div><span>THỜI GIAN BẮT ĐẦU</span><strong>10/10 · ${match.time}</strong></div><div><span>TRẠNG THÁI</span><strong class="status-text">${replay?'Đang xem replay':waiting?'Chưa bắt đầu':paused?'Tạm dừng':'Đang theo dõi'}</strong></div><div><span>LƯỢT HIỆN TẠI</span><strong id="current-turn">${step}</strong></div><div><span>NƯỚC ĐI MỚI NHẤT</span><strong id="latest-move">${latest?latest.from+' → '+latest.to:'Chưa có nước đi'}</strong></div></div></section><section class="panel"><div class="history-tabs"><button class="${state.historyTab==='moves'?'active':''}" data-action="history-tab" data-value="moves">Nước đi <span class="count-bubble" id="history-count">${step}</span></button><button class="${state.historyTab==='events'?'active':''}" data-action="history-tab" data-value="events">Sự kiện</button></div><div id="history-content">${state.historyTab==='moves'?`<div class="history-list" id="history-list" tabindex="0" aria-label="Lịch sử nước đi">${moveHistory||'<div class="empty-state" style="padding:45px 15px"><p>Trận đấu chưa có nước đi.</p></div>'}</div>`:`<div class="status-log">[${match.time}] Hai đội vào phòng đấu.<br>[${match.time}] Phiên bản bot đã chốt.<br>[${match.time}] Bắt đầu ghi nhận lượt.<br>${paused?'[14:02] Tạm dừng kỹ thuật.<br>Đang chờ kết nối lại.':'Kết nối người xem: đang hoạt động.'}<br><br>Nhật ký minh họa · Demo UI</div>`}</div><div class="history-footer">${icon('shield')}Nước đi và trạng thái là dữ liệu minh họa</div></section><div class="technical-notice ${paused?'paused-note':''}">${icon(paused?'clock':'radio')}<div><strong>${waiting?'Trận đấu chưa bắt đầu':paused?'Diễn biến đang tạm dừng':'Bạn đang ở chế độ người xem'}</strong>${waiting?'Hai đội sẽ vào trận theo lịch đã chốt. Bạn có thể thử diễn biến bằng nút demo.':paused?'Đội đang kết nối lại. Trên hệ thống thật, thời gian pause và quyền tiếp tục do server quản lý.':'Bot tự chọn nước đi. Bạn có thể bấm vào một ô để xem tọa độ; thao tác này không điều khiển bot.'}</div></div></aside></div><section class="arena-other">${sectionHead('Cùng lúc trên đấu trường','',navLink('live','Tất cả trận'))}<div class="match-grid">${matchesFor(state).filter(m=>['live','paused'].includes(m.status)&&m.id!==match.id).slice(0,2).map(m=>matchCard(m,true)).join('')}</div></section>`;
}

export function guide() {
  return `${head('Bắt đầu bằng một nước đi','Tài liệu ngắn gọn để bạn viết bot đầu tiên và tham gia đấu trường.',`<a class="btn primary" href="assets/bot-starter-cpp.zip" download>${icon('download')}Tải bot mẫu C++</a><a class="btn" href="assets/bot-starter-codon.zip" download>Python + Codon</a><a href="#/benchmark" class="btn primary">Test & benchmark</a>`)}<div class="guide-grid"><section class="panel guide-card">${icon('code')}<div class="eyebrow">01 / VIẾT BOT</div><h2>Tập trung vào chiến thuật</h2><p>Adapter đảm nhiệm giao tiếp. Bot của bạn nhận trạng thái và trả về một hành động.</p><pre>json choose_move(const json&amp; state,<br>                 const json&amp; legal_moves) {<br>    return legal_moves.empty() ? json(nullptr)<br>                               : legal_moves[0];<br>}</pre><div class="runtime-policy-note"><strong>C++17 là mặc định.</strong> Python + Codon là lựa chọn thử nghiệm khi đội đồng ý dùng. Build và benchmark đúng runtime trước khi chốt. Quay lại C++ cần source C++ và một phiên bản nộp mới.</div><ol><li>Tải và giải nén bot mẫu.</li><li>Mở thư mục bằng VS Code.</li><li>Thay đổi hàm choose_move.</li><li>Thử với observation mẫu trong README.</li><li>Đóng gói .zip và lưu phiên bản.</li></ol></section><section class="panel guide-card">${icon('grid')}<div class="eyebrow">02 / HIỂU TRÒ CHƠI</div><h2>OTT v2 · Búa, Bao, Kéo</h2><p>Bàn đấu 9×9 với cơ chế khắc chế quen thuộc và những quyết định chiến thuật mới.</p><ul class="check-list"><li>${icon('check')}Búa thắng Kéo · Kéo thắng Bao · Bao thắng Búa.</li><li>${icon('check')}Mục tiêu: chiếm căn cứ hoặc loại hết một loại quân của đối thủ.</li><li>${icon('check')}Đội thi cải thiện heuristic, tìm kiếm và quản lý thời gian.</li></ul><div class="info-note">${icon('info')}Luật di chuyển, hòa và giới hạn lượt cần được chốt trong đặc tả game. Bàn demo hiện minh họa giao diện, chưa thực thi đầy đủ luật OTTv2.</div></section><section class="panel guide-card">${icon('shield')}<div class="eyebrow">03 / THAM GIA GIẢI</div><h2>Cùng đội, cùng một phiên bản</h2><p>Mỗi đội có 3–4 thành viên. Đội trưởng quản lý đội và nộp bot; phiên bản dùng cho mỗi vòng được chốt trước khi thi đấu.</p><ul class="check-list"><li>${icon('check')}Tạo đội và hoàn thành thông tin thành viên.</li><li>${icon('check')}Nộp source C++ hoặc chọn Python + Codon và xác nhận thử nghiệm.</li><li>${icon('check')}Đội tự chuẩn bị laptop và kết nối mạng cho chế độ hybrid.</li><li>${icon('check')}Xem lịch, vào phòng đấu và theo dõi replay sau trận.</li></ul>${navLink('team','Xem đội của bạn','text-link','arrow')}</section><section class="panel guide-card">${icon('radio')}<div class="eyebrow">04 / KẾT NỐI & KHÔI PHỤC</div><h2>Bot local. Trọng tài server.</h2><p>Server quyết định trạng thái, đồng hồ và tính hợp lệ của nước đi. Adapter tách khỏi bot để duy trì kết nối khi bot đang tính.</p><ul class="check-list"><li>${icon('check')}Heartbeat giúp phát hiện kết nối bị gián đoạn.</li><li>${icon('check')}Reconnect nhận lại snapshot và phiên điều khiển mới.</li><li>${icon('check')}Technical pause phải có giới hạn theo thể lệ.</li><li>${icon('check')}Hash source hỗ trợ đối chiếu, không chứng minh toàn bộ hành vi trên máy đội thi.</li></ul><div class="info-note">${icon('info')}Đây là bản thiết kế giao diện. Đăng nhập UET, adapter và các kiểm tra server sẽ được tích hợp ở giai đoạn backend.</div></section></div>`;
}

export const login=loginView;

export function renderPage(state) {
  if(state.route==='login')return loginView(state);
  if(state.route==='register')return registrationView(state);
  if(state.route==='change-password')return changePasswordView(state);
  if(state.route==='recover')return recoveryView(state);
  if(state.route==='admin')return shell(state,accountsView(state));
  if(['team','submissions','benchmark'].includes(state.route)&&!state.user)return shell(state,`<section class="admin-entry panel"><span class="auth-success-mark">${icon('shield')}</span><div class="eyebrow">TÀI KHOẢN ĐỘI THI</div><h1>Đăng nhập để quản lý đội.</h1><p>Dùng tài khoản do ban tổ chức cấp để quản lý thành viên, phiên bản bot và hồ sơ đội.</p><a class="btn primary" href="#/login">Đăng nhập ${icon('arrow')}</a><a class="text-link" href="#/register">Chưa có đội? Đăng ký tham gia</a></section>`);
  const pages={home,live,schedule,standings,team,submissions,guide,benchmark};
  const content=['arena','replay'].includes(state.route)?arena(state,state.route==='replay'):(pages[state.route]||home)(state);
  return shell(state,content);
}
